<div class="garden-grid"><label>Customer<select name="customer_id" data-garden-select hidden><option value="">Choose Customer</option><?php foreach ($garden_customers as $c): ?><option value="<?= (int)$c->id; ?>"><?= htmlspecialchars($c->customer_name); ?></option><?php endforeach; ?></select></label>
<label>Customer Site<select name="site_id" data-garden-select hidden><option value="">No Saved Site</option><?php foreach ($garden_sites as $s): ?><option value="<?= (int)$s->id; ?>"><?= htmlspecialchars($s->customer_name.' — '.($s->site_name ?: $s->address)); ?></option><?php endforeach; ?></select></label>
<label>Assigned Team Member<select name="assigned_user_id" data-garden-select hidden><option value="">Unassigned</option><?php foreach ($garden_staff as $s): ?><option value="<?= (int)$s->id; ?>"><?= htmlspecialchars($s->username); ?></option><?php endforeach; ?></select></label></div>
